                let lists: List<any Sequence<String>> = List<any Sequence<String>>(AlphaTex1LanguageDefinitions.scoreMetaDataSignatures.keys(), AlphaTex1LanguageDefinitions.structuralMetaDataSignatures.keys(), AlphaTex1LanguageDefinitions.staffMetaDataSignatures.keys(), AlphaTex1LanguageDefinitions.barMetaDataSignatures.keys())
                for l in lists {
                    for v in l {
                        self._allKnownBarMetaDataTags!.add(v)
                    }
